<script lang="ts">
  import ColorFilter from './ColorFilter.svelte';
  import { emptyFilters } from '../lib/scryfall';
  import type { SearchFilters } from '../lib/scryfall';
  let { filters = $bindable(), unique = $bindable('cards'), direction = $bindable('auto'), exactQuery = '', excludedNames = [], legalList = false }: { filters: SearchFilters; unique?: 'cards' | 'art' | 'prints'; direction?: 'auto' | 'asc' | 'desc'; exactQuery?: string; excludedNames?: string[]; legalList?: boolean } = $props();
  let copied = $state(false);
  async function copyQuery() { try { await navigator.clipboard.writeText(exactQuery); copied = true; } catch { copied = false; } }
  const formats = ['standard', 'pioneer', 'modern', 'legacy', 'vintage', 'commander', 'pauper', 'penny', 'brawl', 'historic', 'timeless', 'alchemy'];
</script>
<details class="advanced-search">
  <summary>Advanced search</summary>
  <div class="advanced-fields">
    <div class="form-grid"><label>Card name<input bind:value={filters.name} placeholder="Name contains" /></label><label>Rules text (all phrases)<input bind:value={filters.oracle} placeholder={'"whenever", "draw a card"'} /></label><label>Types<input bind:value={filters.type} placeholder="legendary creature" /></label><label>Type matching<select bind:value={filters.typeMode}><option value="all">All these types</option><option value="any">Any of these types</option></select></label><label>Exclude types<input bind:value={filters.excludeType} placeholder="e.g. artifact enchantment" /></label><label>Mana cost<input bind:value={filters.manaCost} placeholder={'e.g. {1}{U}'} /></label></div>
    <ColorFilter label="Colors" value={filters.colors} mode={filters.colorMode} onchange={(v) => filters.colors = v} onmode={(v) => filters.colorMode = v} />
    <ColorFilter label="Color identity" value={filters.identity} mode={filters.identityMode} onchange={(v) => filters.identity = v} onmode={(v) => filters.identityMode = v} />
    <div class="form-grid"><label>Mana value<input bind:value={filters.manaValue} placeholder="e.g. <=3" /></label><label>Power<input bind:value={filters.power} placeholder="e.g. >=2" /></label><label>Toughness<input bind:value={filters.toughness} placeholder="e.g. =4" /></label><label>Loyalty<input bind:value={filters.loyalty} placeholder="e.g. >=3" /></label><label>Rarity<select bind:value={filters.rarity}><option value="">Any rarity</option><option value="common">Common</option><option value="uncommon">Uncommon</option><option value="rare">Rare</option><option value="mythic">Mythic</option><option value="special">Special</option><option value="bonus">Bonus</option></select></label><label>Printing sets<input bind:value={filters.sets} placeholder="e.g. mh3, dmu" /></label><label>Block<input bind:value={filters.block} placeholder="A set code in the block" /></label><label>Format<select bind:value={filters.legalFormat}><option value="">Any format</option>{#each formats as f}<option value={f}>{f[0].toUpperCase() + f.slice(1)}</option>{/each}</select></label><label>Format legality<select bind:value={filters.legality}><option value="legal">Legal</option><option value="banned">Banned</option><option value="restricted">Restricted</option></select></label><label>Game<select bind:value={filters.game}><option value="">All games</option><option value="paper">Paper</option><option value="arena">Arena</option><option value="mtgo">Magic Online</option></select></label><label>Artist<input bind:value={filters.artist} /></label><label>Flavor text<input bind:value={filters.flavor} /></label><label>Language<select bind:value={filters.language}><option value="">Any language</option><option value="en">English</option><option value="de">German</option><option value="fr">French</option><option value="it">Italian</option><option value="es">Spanish</option><option value="pt">Portuguese</option><option value="ja">Japanese</option><option value="ko">Korean</option><option value="ru">Russian</option><option value="zhs">Simplified Chinese</option><option value="zht">Traditional Chinese</option></select></label><label>Border<select bind:value={filters.border}><option value="">Any border</option><option value="black">Black</option><option value="white">White</option><option value="silver">Silver</option><option value="borderless">Borderless</option></select></label><label>Released on or after<input type="date" bind:value={filters.releasedAfter} /></label><label>Released on or before<input type="date" bind:value={filters.releasedBefore} /></label><label>Price<input bind:value={filters.price} placeholder="e.g. <=5" /></label><label>Currency<select bind:value={filters.currency}><option value="usd">USD</option><option value="eur">EUR</option><option value="tix">TIX</option></select></label><label>Result grouping<select bind:value={unique}><option value="cards">One per card</option><option value="art">One per artwork</option><option value="prints">All printings</option></select></label></div>
    <p class="help">The search box also accepts all <a href="https://scryfall.com/docs/syntax" target="_blank" rel="noreferrer">Scryfall syntax</a>. Numeric fields accept comparisons such as <code>&lt;=3</code>.</p>
    {#if legalList}<p class="help">Legal card lists are searched in batches. The query below shows the most recent batch.</p>{/if}<label>Exact Scryfall query<textarea readonly value={exactQuery} rows="3" class="exact-query" onfocus={(e) => e.currentTarget.select()}></textarea></label><div class="transfer-actions"><button class="secondary" type="button" onclick={copyQuery}>{copied ? 'Copied' : 'Copy query'}</button><a href={`https://scryfall.com/search?q=${encodeURIComponent(exactQuery)}`} target="_blank" rel="noreferrer">Open on Scryfall ↗</a></div>{#if excludedNames.length}<p class="help">{excludedNames.length} named format bans are filtered locally after Scryfall returns results.</p>{/if}
    <button class="quiet" type="button" onclick={() => { filters = emptyFilters(); unique = 'cards'; direction = 'auto'; }}>Clear advanced filters</button>
  </div>
</details>
